<script setup>defineProps({label:String,description:String,modelValue:Boolean});defineEmits(["update:modelValue"])</script><template><label class="kit-switch-row"><view><text class="kit-label">{{label}}</text><text v-if="description" class="kit-secondary">{{description}}</text></view><switch :checked="modelValue" color="#006aff" @change="$emit('update:modelValue',$event.detail.value)"/></label></template>